  rose: () => `<path d="M50 54V98" stroke="${C.G}" stroke-width="3"/><path d="M50 72Q36 64 32 72Q40 80 50 74Z" fill="${C.G}"/><path d="M50 84Q64 76 68 84Q60 92 50 86Z" fill="${C.G}"/><circle cx="50" cy="36" r="17" fill="${C.R}"/><path d="M33 36Q33 56 50 56Q67 56 67 36Q58 48 50 48Q42 48 33 36Z" fill="${C.R}" opacity=".85"/><path d="M50 28q7 0 7 7t-7 7t-7-7t7-10" stroke="${C.K}" stroke-width="1.6" fill="none" opacity=".35"/>`,
  wrose: () => `<path d="M50 54V98" stroke="${C.G}" stroke-width="3"/><path d="M50 72Q36 64 32 72Q40 80 50 74Z" fill="${C.G}"/><path d="M50 84Q64 76 68 84Q60 92 50 86Z" fill="${C.G}"/><circle cx="50" cy="36" r="17" fill="${C.W}"/><path d="M33 36Q33 56 50 56Q67 56 67 36Q58 48 50 48Q42 48 33 36Z" fill="#ece2cc"/><path d="M50 28q7 0 7 7t-7 7t-7-7t7-10" stroke="#b8a888" stroke-width="1.6" fill="none"/>`,
  lotus: () => `<ellipse cx="50" cy="84" rx="40" ry="8" fill="${C.G}"/><path d="M50 30Q38 54 50 78Q62 54 50 30Z" fill="${C.P}"/><path d="M50 78Q26 66 22 44Q42 50 50 78Z" fill="${C.P}" opacity=".9"/><path d="M50 78Q74 66 78 44Q58 50 50 78Z" fill="${C.P}" opacity=".9"/><path d="M50 78Q20 76 12 62Q34 60 50 78Z" fill="${C.P}" opacity=".75"/><path d="M50 78Q80 76 88 62Q66 60 50 78Z" fill="${C.P}" opacity=".75"/>`,
  palm: () => `<path d="M54 98Q48 66 58 32" stroke="${C.N}" stroke-width="6" fill="none"/>` + [[-150, 34], [-115, 30], [-70, 32], [-30, 34], [10, 28]].map(([a, l]) => { const r = a * Math.PI / 180, x = 58 + l * Math.cos(r), y = 32 + l * Math.sin(r); return `<path d="M58 32Q${(58 + x) / 2 + 6 * Math.sin(r)} ${(32 + y) / 2 - 8} ${x} ${y}Q${(58 + x) / 2} ${(32 + y) / 2} 58 34Z" fill="${C.G}"/>`; }).join(''),
