  carrot: () => `<path d="M34 34Q54 30 66 40L30 92Q26 96 26 88Z" fill="${C.F}"/><path d="M40 46l8 2M36 58l7 2M32 72l6 1" stroke="${C.K}" stroke-width="1.4" opacity=".3"/><path d="M58 36Q62 14 54 6Q70 16 64 36ZM62 38Q80 20 92 22Q80 34 66 42ZM60 37Q74 10 82 6Q80 26 66 40Z" fill="${C.G}"/>`,

